import{_ as a,o as p,c as t,a3 as r}from"./chunks/framework.d6OaePA7.js";const h=JSON.parse('{"title":"心意册小程序开发的感受","description":"","frontmatter":{},"headers":[],"relativePath":"pages/explore/share/一些微信小程序开发的感受.md","filePath":"pages/explore/share/一些微信小程序开发的感受.md","lastUpdated":1789460784000}'),o={name:"pages/explore/share/一些微信小程序开发的感受.md"};function _(s,e,l,n,i,d){return p(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="心意册小程序开发的感受" tabindex="-1">心意册小程序开发的感受 <a class="header-anchor" href="#心意册小程序开发的感受" aria-label="Permalink to &quot;心意册小程序开发的感受&quot;">​</a></h1><blockquote><p>随便写写，没有格式</p></blockquote><h2 id="一、-方向和努力哪个更重要" tabindex="-1">一、 方向和努力哪个更重要？ <a class="header-anchor" href="#一、-方向和努力哪个更重要" aria-label="Permalink to &quot;一、 方向和努力哪个更重要？&quot;">​</a></h2><p>这个方向主要是源于我和一个群内大佬的对比。群内我和大佬都不是第一个使用 AI 做小程序全流程开发，然后独立上线的，第一位大佬是一个做记工小程序的，当时经常在群内发自己的小程序，进而引发了许多人也做一个小程序的冲动。</p><p>我一开始是打算记录这样一个小程序：记录传统交往中的随份子，随礼这种往来，客户有点偏向于中老年人，也能涵括一部分青年。但是在后续的开发中，我逐渐意识到如果只是这种偏厚重，传统的随份子场景，小程序固然够细分聚焦，但是中老年人群有点不好扩展，随份子也是一次性动作，进一步的盈利也难如登天。所以，我又基于小程序记录人情往来的主题，新增了更轻盈，没有较重负担的朋友节日祝福往来场景。当然我也不是只新增记录，还设想了其他高级功能，如心意星球，通过炫酷的动效来支撑高级功能的门面；心意提醒，当别人送给我礼物的时候，我在记录的同时可以添加会送提醒，到期前提醒我要准备礼物，通过提醒功能解决用户可能遗忘的忧虑；其他还有心意瞬间等功能。</p><p>在小程序的推广上，由于我前期意向客户是中老年 + 一部分青年，所以选择了 快手 + 小红书的组合。但是快手发了几个没有什么效果，所以我就暂停了，目前主要是发小红书，前期内容就是一些产品的新功能，产品介绍，数据比较差。另外我还在 v2ex 上发了一条广告，带来了 10 个左右的新用户，其他就没什么推广了。最后就是熟人网络的推广，这个大概也是 10 个左右新用户。</p><p>群内另一位大佬做的小美评审团小程序就是一个比较成功的典型。这个小程序源于美团新增的一个评审团功能，类似于闲鱼的小法庭，用户可以获得俸银兑换东西。就是这么一个很细分，让我不经常点外卖的人去找都不容易找的功能，做成了一个评审题库，然后用户量突破了 500，加了广告后每天收益有 10+。我大概总结了一下小程序的成功，首先就是这个功能足够细分，然后他自己也玩，还加了大伙自己组件的评审团群，群里都是意向客户，前期推广压力不大；其次发现了题库这个需求，然后在网上搜索以及其他人贡献了一部分，形成了初步的题库；最后就是小程序的用户（羊毛党，偏闲暇人群）天然能够接受用广告来换取自己利益。</p><p>这也就引出来标题了：方向和努力哪个更重要？</p><p>用户群体要确认，确认了群体就知道怎么盈利，比如小美评审团，有时间玩这个的，可能大多数都是羊毛党，可以接受用时间/广告换 money，接受度高，适合开发免费小程序 + 广告的方式盈利；但是如果用户群体是羽毛球选手（只是示例因为好的羽毛球挺贵的...），大多数可能比较在意体验，如果广告太多，那么就不行，这时候需要从其他方向去提升用户体验，然后盈利。</p><p>就像是很出名的一句话：穷人的好骗不好赚，富人的钱好赚不好骗。</p><p>又想了下，随着大模型能力的提升，同一个产品赛道肯定会有越来越多的人去搞，这时候去收费难度就会很大，当然这也可能是我的臆想，毕竟互联网上发声且真的去做产品的人还是占比很小的。我还是先做做再说，至少也是一段不可磨灭的记忆。</p><h2 id="二、-小程序宣传方面的一些总结" tabindex="-1">二、 小程序宣传方面的一些总结 <a class="header-anchor" href="#二、-小程序宣传方面的一些总结" aria-label="Permalink to &quot;二、 小程序宣传方面的一些总结&quot;">​</a></h2><p>首先是一两周除了小红书宣传平台，新增了微博和抖音两个平台，看看新增两个平台后数据怎么样。</p><p>其次，在看了小红书上其他产品的推广后，我知道自己流量差的原因了，前期帖子过于粗糙（大字报 + 原生手机截图），好的帖子应该从第一眼（封面）吸引到用户，所以我又做了一个 share-studio 产品，专门解析小红书产品宣传帖的图片，然后让 ai 把我的页面嵌入到这些模板中。</p><p>最后，就是经常使用当前小红书账号进行浏览和评论，增加账号的活跃度，提升真人感。</p><p>在经过这一番操作后，小程序新增用户依然是个位数，甚至是一天 1 个，一天 0 个这种。好在经过我自己不断的和其他帖子互动，小红书的浏览量相比于之前大字报时期要好太多，突破了每篇个位数的困境。</p><p>但是，随着最近小程序改版页面的上线，短期内没有太多明显的改动了，所以我有点犹豫是先继续进行项目优化，还是进行一些新的大功能（瞬间/记账）的开发，亦或者是停下来，先做下小程序的宣传，积累用户量，看下用户有没有真的用起来再做决定。在写这篇文章的时候我突然想到最近马上就是国庆，国庆节结婚的应该会不少，那貌似就是我小程序宣传的好时机。不多说了，我觉得我找到现阶段的答案了，先去想想怎么把国庆这个时间段利用起来。</p>',17)])])}const u=a(o,[["render",_]]);export{h as __pageData,u as default};
